import java.sql.*;
import javax.servlet.http.*;

public class UserLookupServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws Exception {
        String username = request.getParameter("username");
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/webapp", "user", "pass");
        // Using PreparedStatement with parameterized queries safely separates SQL logic from user data
        String sql = "SELECT * FROM users WHERE username = ?";
        PreparedStatement pstmt = conn.prepareStatement(sql);
        pstmt.setString(1, username);
        ResultSet rs = pstmt.executeQuery();
        // process ResultSet...
        rs.close();
        pstmt.close();
        conn.close();
    }
}
