    "2_Needs_Improvement": "Frequently falls short of expectations. Requires significant support to meet role requirements. Performance gaps are impacting work or team.",
    "1_Unsatisfactory": "Performance is significantly below expectations. Immediate intervention required. Unable to perform core responsibilities independently."
  },
  "categories": [
    {
      "id": "technical_excellence",
      "name": "Technical Excellence & Code Quality",
      "weight": 0.30,
      "description": "Evaluates the quality, reliability, and maintainability of technical output.",
      "criteria": [
        {
          "name": "Code Quality & Maintainability",
          "descriptors": {
            "5": "Code is exemplary: clean, modular, well-documented, and highly maintainable. Proactively refactors legacy code and sets standards for the team.",
            "4": "Code is clean, follows best practices, and is easy to maintain. Rarely requires refactoring. Adheres to style guides and conventions.",
            "3": "Code is functional and mostly clean but may lack consistency, documentation, or optimal structure in places.",
            "2": "Code is often messy, hard to read, or violates style guides. Requires frequent refactoring by others.",
            "1": "Code is unreadable, buggy, or unmaintainable. Creates significant technical debt."
          }
        },
        {
          "name": "Testing & Reliability",
          "descriptors": {
            "5": "Advocates for robust testing strategies. Writes comprehensive unit/integration/E2E tests. Proactively improves system reliability and observability.",
            "4": "Writes adequate tests for features. Ensures code is reliable and covers edge cases. Maintains test coverage.",
            "3": "Writes tests but coverage may be incomplete. Relies on QA to catch some issues. Tests may be brittle.",
            "2": "Tests are sparse or ineffective. Features often have regressions. Neglects edge cases.",
            "1": "Neglects testing entirely. Code is fragile and breaks frequently. No test coverage."
          }
        },
        {
          "name": "Technical Best Practices",
          "descriptors": {
            "5": "Champions security, performance, and accessibility. Introduces new tools or patterns that benefit the organization.",
            "4": "Consistently applies security, performance, and accessibility standards. Uses appropriate tools and patterns.",
            "3": "Applies best practices but may overlook non-functional requirements occasionally.",
            "2": "Frequently ignores best practices. Security or performance issues are common.",
            "1": "Disregards best practices. Code poses security risks or performance bottlenecks."
