      "weight": 0.25,
      "description": "Assesses the ability to analyze problems, design solutions, and debug effectively.",
      "criteria": [
        {
          "name": "Technical Design & Architecture",
          "descriptors": {
            "5": "Designs scalable, secure, and efficient solutions. Anticipates future needs and edge cases. Influences architectural direction and trade-off analysis.",
            "4": "Creates sound designs that meet requirements. Considers scalability and trade-offs appropriately. Designs are approved with minor feedback.",
            "3": "Designs are functional but may overlook scalability, maintainability, or non-functional requirements.",
            "2": "Designs are often flawed, overly complex, or insufficient. Requires significant rework or guidance.",
            "1": "Unable to design solutions independently. Designs lead to system failures or block progress."
          }
        },
        {
          "name": "Debugging & Troubleshooting",
          "descriptors": {
            "5": "Rapidly diagnoses complex, systemic, or intermittent issues. Implements root cause fixes and prevents recurrence. Mentors others in debugging.",
